/* eslint-disable max-len -- Standalone HTML template, matching the adaptive page. */
import express from 'express';
const router = express.Router();
router.get('/sensors', (_req, res) => res.set('Cache-Control', 'private, no-store').type('html').send(`<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pod sensors</title>
<style>body{font:16px system-ui;max-width:960px;margin:32px auto;padding:0 20px;color:#252525;background:#fafafa}a{color:inherit}section{padding:18px 0;border-bottom:1px solid #ccc}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:6px;border-bottom:1px solid #eee}p{line-height:1.5}.warning{color:#9a3412}h2{font-size:20px}button{padding:8px}</style>
<a href="/status">Status</a> · <a href="/adaptive-temperature">Adaptive temperature</a><h1>Pod sensors</h1>
<p id="connection" role="status">Loading readings…</p><p>Live data confirms a reporting channel. It does not verify physical button presses, vibration, optional accessories or sensor accuracy. Connector flags do not prove an accessory is installed.</p>
<section><h2>Latest stored biometric estimates</h2><div id="vitals"></div><p>HRV is SDNN. Unavailable means no fresh accepted estimate in the stored records; it is not zero. Sleep stages are estimates, not independently validated measurements.</p></section>
<main id="samples"></main><section><h2>History</h2><p>Hardware readings are sampled once per minute and retained for 90 days. Raw data retains its separate 36-hour limit.</p><label>Channel <select id="kind"></select></label> <button id="download">Download last 24 hours</button><p id="historyStatus" role="status"></p></section>
<script>
const names={frzTemp:'Hub temperatures (°C)',frzHealth:'Pumps, fans and thermal readings',frzTherm:'Thermal controller',bedTemp:'Cover temperatures and humidity',sensHealth:'Cover connections',blanketReadings:'Blanket connector and orientation',capSense:'Capacitance status'};
const kind=document.getElementById('kind');for(const [value,label] of Object.entries(names)){const option=document.createElement('option');option.value=value;option.textContent=label;kind.append(option);}
async function refresh(){try{const response=await fetch('/api/sensors',{cache:'no-store'});if(!response.ok)throw Error('Sensor service unavailable');const data=await response.json();document.getElementById('historyStatus').textContent=data.historyError||'';
document.getElementById('connection').textContent='Connected. Readings update every 10 seconds. Automatic temperature sensor checks: left '+(data.ready.left?'ready':'waiting')+', right '+(data.ready.right?'ready':'waiting')+'.';
document.getElementById('vitals').replaceChildren();for(const row of data.vitals){const p=document.createElement('p');p.textContent=row.side+': heart rate '+row.heartRate+' · HRV '+row.hrv+' · breathing '+row.breathing;document.getElementById('vitals').append(p);}
const main=document.getElementById('samples');main.replaceChildren();for(const sample of data.samples){const section=document.createElement('section'),heading=document.createElement('h2'),state=document.createElement('p'),table=document.createElement('table');heading.textContent=names[sample.kind];state.textContent=sample.state+(sample.age===null?'':' · '+Math.max(0,Math.round(sample.age))+' seconds old');if(sample.state!=='live')state.className='warning';section.append(heading,state);for(const [key,value] of Object.entries(sample.fields)){const tr=document.createElement('tr'),label=document.createElement('td'),reading=document.createElement('td');label.textContent=key;reading.textContent=sample.state!=='live'?'Unavailable (stale)':value===null?'Unavailable':typeof value==='number'?String(Math.round(value*100)/100):String(value);tr.append(label,reading);table.append(tr);}section.append(table);main.append(section);}
}catch(error){document.getElementById('connection').textContent=error.message+' — previous readings are not confirmed live.';document.getElementById('samples').replaceChildren();document.getElementById('vitals').textContent='Unavailable';}}
document.getElementById('download').onclick=async()=>{try{const end=Math.floor(Date.now()/1000);const response=await fetch('/api/sensors/history?kind='+encodeURIComponent(kind.value)+'&start='+(end-86400)+'&end='+end);if(!response.ok)throw Error('History unavailable');const rows=await response.json(),url=URL.createObjectURL(new Blob([JSON.stringify(rows,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='pod-sensors-'+kind.value+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('historyStatus').textContent=rows.length+' records exported.';}catch(error){document.getElementById('historyStatus').textContent=error.message;}};
refresh();setInterval(refresh,10000);
</script></html>`));
export default router;
